from pathlib import Path
import re, json, html

root = Path(__file__).parent
template = (root / '_template.html').read_text(encoding='utf-8')
template = re.sub(r'<link[^>]+>', '', template)
template = template.replace("'Plus Jakarta Sans', ", '').replace("'Fraunces', ", '')
template = re.sub(r'/\*.*?\*/', '', template, flags=re.S)
(root / '_template.html').write_text(template, encoding='utf-8')
base_style = re.search(r'<style>(.*?)</style>', template, re.S).group(1)

def icon(name, size=24):
    paths = {
        'book':'<path d="M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H4zM20 4h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 4-3h3z"/>',
        'star':'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z"/>',
        'flame':'<path d="M13 2c1 7-5 6-4 11 2 0 4-2 4-4 5 3 6 6 4 10-2 4-9 4-11 0C2 12 10 9 13 2z"/>',
        'cup':'<path d="M7 3h10v7a5 5 0 0 1-10 0zM7 5H3v3c0 3 2 4 4 4m10-7h4v3c0 3-2 4-4 4m-5 3v6m-4 0h8"/>',
        'home':'<path d="m3 10 9-7 9 7M5 9v12h14V9M10 21v-7h4v7"/>',
        'user':'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>',
        'check':'<path d="m5 12 4 4L19 6"/>',
        'lock':'<rect x="6" y="10" width="12" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
        'arrow':'<path d="M4 12h16m-6-6 6 6-6 6"/>',
        'sun':'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',
        'leaf':'<path d="M20 3C7 1 0 10 7 17S22 14 20 3ZM5 21 16 8"/>',
    }
    return f'<svg width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{paths[name]}</svg>'

