phrase, translation, record_id = '','', ''
sample = root / 'dataset-sample.json'
if sample.exists():
    data = json.loads(sample.read_text(encoding='utf-8-sig'))
    for row in data.get('rows', []):
        r = row['row']
        if r.get('text_ba') and r.get('text_ru'):
            phrase, translation, record_id = r['text_ba'], r['text_ru'], str(r.get('id', row['row_idx']))
            break

stats = f'<div class="stats"><span class="streak">{icon("flame",20)} 3 дня</span><span>{icon("star",20)} 120 XP</span><span class="avatar">А</span></div>'
brand = f'<div class="brand">{icon("leaf",25)} bashlingo<span>БА</span></div>'
nav = ''.join(f'<span class="nav-item {"active" if i==0 else ""}">{icon(ic,21)}<span>{label}</span></span>' for i,(ic,label) in enumerate([('book','Учиться'),('sun','Задание дня'),('home','Мой класс'),('cup','Рейтинг'),('user','Профиль')]))
def small_cards():
    return f'<div class="small-cards"><div class="mini-card"><span class="label">{icon("sun",18)} ЛИЧНАЯ ПРАКТИКА</span><strong>Задание дня</strong><p>5 упражнений под твой уровень</p><button class="text-btn" data-action="daily">Начать {icon("arrow",18)}</button></div><div class="mini-card"><span class="label">{icon("home",18)} ОТ УЧИТЕЛЯ</span><strong>Моя семья</strong><p>6 карточек · твой класс</p><button class="text-btn" data-action="homework">Открыть {icon("arrow",18)}</button></div></div>'
def progress():
    return '<div class="progress-line"><span>Цель на сегодня</span><b>10 / 20 XP</b></div><div class="progress"><i></i></div>'
def footer():
    return '<div class="bottom-nav">'+''.join(f'<span class="{"selected" if i==0 else ""}">{icon(ic,23)}<small>{label}</small></span>' for i,(ic,label) in enumerate([('book','Уроки'),('sun','Сегодня'),('home','Класс'),('user','Профиль')]))+'</div>'
def path_nodes():
    return f'<div class="path"><div class="trail"></div><div class="node n1 done">{icon("check",28)}</div><div class="node n2 done">{icon("check",28)}</div><div class="current-label">ТЫ ЗДЕСЬ</div><button class="node n3" data-action="lesson" aria-label="Начать урок знакомства">{icon("star",34)}</button><div class="node n4 locked">{icon("lock",24)}</div><div class="node n5 locked">{icon("cup",28)}</div><div class="path-friend">{marten()}<div class="bubble">Ещё один шаг?<br><b>У тебя получится!</b></div></div></div>'

variants = [
('A','Тропа знаний','Самый игровой: следующий урок всегда очевиден. Задания класса занимают второй план.',f'''<div class="va-app app"><aside>{brand}<div class="side-nav">{nav}</div><div class="side-note">Маленькие шаги.<br><b>Большие открытия.</b>{icon('leaf',34)}</div></aside><div class="workspace"><header class="app-header"><span>ТВОЙ ПУТЬ</span>{stats}</header><div class="va-layout"><div class="va-main"><div class="chapter"><div><span class="label">РАЗДЕЛ 1 · ПЕРВЫЕ СЛОВА</span><h2>Давай знакомиться!</h2><p>Начни разговор на башкирском</p></div>{icon('book',38)}</div>{path_nodes()}<div class="next-topic">{icon('lock',18)} Дальше — «Моя семья»</div></div><div class="va-rail"><div class="goal"><h3>Растём каждый день</h3>{progress()}<div class="week"><b>П</b><b>В</b><b>С</b><span>Ч</span><span>П</span><span>С</span><span>В</span></div></div>{small_cards()}<div class="community">{icon('leaf',25)}<div><b>Твой язык. Твой вклад.</b><p>Замечай ошибки в переводах — помогай Bashlingo расти.</p></div></div></div></div>{footer()}</div></div>''','Выбирай, если главный приоритет — ощущение Duolingo и понятный маршрут.'),
('B','Один маленький шаг','Самый спокойный: сразу ведёт в занятие. Общая структура курса менее заметна.',f'''<div class="vb-app app"><header class="app-header">{brand}{stats}</header><div class="vb-body"><div class="vb-greeting"><span class="label">ХОРОШИЙ ДЕНЬ ДЛЯ НОВЫХ СЛОВ</span><h2>Пять минут.<br>Чуть ближе к своему языку.</h2><p>Продолжим знакомство? Куница уже ждёт.</p></div><div class="vb-hero"><div class="vb-mascot">{marten()}<span class="spark s1">✦</span><span class="spark s2">✧</span></div><div class="vb-lesson"><span class="pill">РАЗДЕЛ 1 · УРОК 3</span><h2>Давай знакомиться!</h2><p>Научись представляться<br>и спрашивать имя собеседника.</p><button class="primary" data-action="lesson">Продолжить урок {icon('arrow',20)}</button><span class="quiet">Короткое занятие · первые слова</span></div></div><div class="vb-progress">{progress()}</div>{small_cards()}<div class="vb-course"><span>{icon('book',22)} Твой курс: Знакомство → Семья → Школа</span><button class="text-btn" data-action="course">Все темы {icon('arrow',18)}</button></div></div>{footer()}</div>''','Выбирай, если важнее быстрый старт и простота на телефоне.'),
('C','Острова открытий','Самый исследовательский: темы видны целиком. Выбор отвлекает от одного следующего шага.',f'''<div class="vc-app app"><header class="app-header">{brand}{stats}</header><div class="vc-body"><div class="vc-heading"><div><span class="label">ТВОЙ МИР БАШКИРСКОГО</span><h2>Каждое слово — открытие.</h2><p>Сегодня начнём с простого разговора.</p></div><div class="vc-guide">{marten()}</div></div><div class="islands"><div class="island current"><div class="island-art">{icon('sun',70)}<span class="hill"></span></div><span class="pill">СЕЙЧАС ИЗУЧАЕМ</span><h3>Знакомство</h3><p>Первые слова и новые друзья</p><div class="dots"><b></b><b></b><i></i><i></i><i></i></div><button class="primary" data-action="lesson">Продолжить {icon('arrow',19)}</button></div><div class="island"><div class="island-art family">{icon('home',70)}<span class="hill"></span></div><span class="label">СЛЕДУЮЩАЯ ТЕМА</span><h3>Моя семья</h3><p>О тех, кто рядом</p><div class="locked-label">{icon('lock',18)} После знакомства</div></div><div class="island"><div class="island-art school">{icon('book',70)}<span class="hill"></span></div><span class="label">ВПЕРЕДИ</span><h3>В школе</h3><p>Учимся говорить о своём дне</p><div class="locked-label">{icon('lock',18)} После темы «Семья»</div></div></div>{small_cards()}<div class="vc-progress">{progress()}</div></div>{footer()}</div>''','Выбирай, если хочется видеть курс как мир с отдельными темами.'),
('D','Мой учебный день','Самый организованный: личная учёба и класс рядом. Меньше ощущения приключения.',f'''<div class="vd-app app"><aside>{brand}<div class="side-nav">{nav}</div><div class="side-note">Твой класс<br><b>Учимся вместе</b>{icon('home',34)}</div></aside><div class="workspace"><header class="app-header"><span>МОЙ УЧЕБНЫЙ ДЕНЬ</span>{stats}</header><div class="vd-body"><div class="vd-welcome"><div><span class="label">ТЫ УЖЕ НА ШАГ ВПЕРЕДИ</span><h2>Продолжим, ученик!</h2><p>Немного практики — и новые слова станут своими.</p></div>{marten()}</div><div class="vd-grid"><div><div class="vd-next"><span class="label">{icon('book',18)} СЛЕДУЮЩИЙ УРОК</span><h2>Давай знакомиться!</h2><p>Раздел 1 · первые слова</p><button class="primary" data-action="lesson">Продолжить {icon('arrow',20)}</button></div>{small_cards()}</div><div class="vd-summary"><h3>Твой прогресс</h3>{progress()}<div class="metric"><span>{icon('flame',26)} Серия занятий</span><b>3 дня</b></div><div class="metric"><span>{icon('star',26)} Всего опыта</span><b>120 XP</b></div><div class="class-callout">{icon('home',30)}<h3>Вместе интереснее</h3><p>Задания учителя и достижения класса — в одном месте.</p><button class="text-btn" data-action="class">Мой класс {icon('arrow',18)}</button></div></div></div></div>{footer()}</div></div>''','Выбирай, если школа и домашние задания так же важны, как личный курс.')]

