sections=''
for letter,title,tradeoff,content,analysis in variants:
    sections+=f'<section class="variant" id="variant-{letter}"><div class="variant-head"><div class="variant-letter">{letter}</div><div class="variant-meta"><h2>{title}</h2><p class="variant-tradeoff">{tradeoff}</p></div></div><div class="preview-frame"><div class="preview-frame-bar">Bashlingo · {letter} · демонстрационный профиль</div><div class="preview">{content}</div></div><div class="variant-analysis"><div class="analysis-block"><p>{analysis}</p></div></div></section>'

safe_phrase = html.escape(phrase or 'Пример появится после загрузки датасета')
safe_translation = html.escape(translation or 'Нет загруженной пары')
modal=f'''<dialog id="lesson"><button class="close" aria-label="Закрыть">×</button><span class="label" id="dialog-label">ПРИМЕР ВЗАИМОДЕЙСТВИЯ</span><h2 id="dialog-title">Выбери перевод</h2><div id="exercise"><p style="font-size:25px;font-weight:700">{safe_phrase}</p><button class="answer" data-correct="true">{safe_translation}</button><button class="answer" data-correct="false">Другой вариант</button><div class="feedback hidden" role="status"></div><div class="report hidden"><b>В переводе ошибка?</b><p><button class="vote" data-vote="yes" aria-label="Перевод верный">👍</button> <button class="vote" data-vote="no" aria-label="В переводе ошибка">👎</button></p><div class="correction hidden"><label>Почему считаешь перевод неверным?<textarea id="reason"></textarea></label><label>Твой вариант (если знаешь)<textarea id="proposal"></textarea></label><button class="primary" id="send-report">Отправить замечание</button></div><p id="report-status" role="status"></p></div></div><div id="info" class="hidden"></div><p class="quiet">Дизайн-прототип. Ответы и замечания не отправляются на сервер.</p></dialog>'''
script='''
const dialog=document.querySelector('dialog');
document.querySelector('.close').onclick=()=>dialog.close();
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelector('.compare-grid').classList.toggle('overview',b.dataset.mode==='overview');document.querySelectorAll('.preview-frame').forEach(f=>f.classList.toggle('mobile',b.dataset.mode==='mobile'))});
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.action;const exercise=['lesson','daily'].includes(a);document.querySelector('#exercise').classList.toggle('hidden',!exercise);document.querySelector('#info').classList.toggle('hidden',exercise);document.querySelector('#dialog-title').textContent=a==='daily'?'Задание дня':a==='lesson'?'Выбери перевод':a==='homework'?'От учителя: Моя семья':a==='course'?'Твой курс':'Мой класс';document.querySelector('#info').textContent=a==='homework'?'Здесь будет назначенный учителем набор из 6 карточек. В макете показана структура, настоящих назначений пока нет.':a==='course'?'Знакомство → Моя семья → В школе. По два коротких урока в каждой теме.':'Присоединение к школе по ссылке или коду, карточки учителя и рейтинг класса.';document.querySelector('.feedback').classList.add('hidden');document.querySelector('.report').classList.add('hidden');document.querySelector('.correction').classList.add('hidden');document.querySelector('#report-status').textContent='';document.querySelectorAll('textarea').forEach(t=>t.value='');dialog.showModal()});
document.querySelectorAll('.answer').forEach(b=>b.onclick=()=>{const f=document.querySelector('.feedback');f.textContent=b.dataset.correct==='true'?'Совпадает с переводом в датасете.':'Попробуй первый вариант: он взят из датасета.';f.classList.remove('hidden');document.querySelector('.report').classList.remove('hidden')});
document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>{document.querySelector('.correction').classList.toggle('hidden',b.dataset.vote!=='no');document.querySelector('#report-status').textContent=b.dataset.vote==='yes'?'Спасибо! В рабочем приложении оценка будет сохранена.':''});
document.querySelector('#send-report').onclick=()=>{const reason=document.querySelector('#reason');if(!reason.value.trim()){document.querySelector('#report-status').textContent='Укажи причину или напиши «не понимаю перевод».';reason.focus();return}document.querySelector('#report-status').textContent='Предпросмотр: замечание попадёт в очередь проверки. В этом макете оно не сохраняется.'};
'''
output=f'''<!-- Bashlingo: четыре направления главного экрана. Источник: согласованный бриф чата и ТЗ. 2026-11-13. -->
<!DOCTYPE html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Bashlingo — выбираем направление</title><style>{base_style}{css}</style></head><body><main class="page"><header class="doc-header"><div class="doc-eyebrow">Bashlingo / исследование дизайна</div><h1 class="doc-title">Свой язык. Свой путь.</h1><p class="doc-subtitle">Четыре способа начать учебный день. Одна куница, одни возможности — разный ритм и акценты.</p><div class="doc-meta"><div><b>Экран</b> Главная ученика</div><div><b>Платформы</b> Сайт + Telegram Mini App</div><div><b>Дата</b> 13.11.2026</div></div><nav class="jump" aria-label="Варианты">{''.join(f'<a href="#variant-{v[0]}">{v[0]} · {v[1]}</a>' for v in variants)}</nav></header><div class="notice">Это варианты дизайна, а не готовое приложение. Прогресс, XP и задания класса — демонстрационные. Нажми «Продолжить» или «Задание дня», чтобы проверить пример ответа и сообщения об ошибке.</div><div class="view-toggle" aria-label="Размер предпросмотра"><button data-mode="full" aria-pressed="true">Большой экран</button><button data-mode="mobile" aria-pressed="false">Телефон / Mini App</button><button data-mode="overview" aria-pressed="false">Рядом для сравнения</button></div><div class="compare-grid">{sections}</div><section class="decision"><h3>Какой Bashlingo ближе тебе?</h3><p class="decision-sub">Рекомендация: A — самый близкий к согласованной игровой подаче. Можно взять главную A и компактную карточку задания из B.</p><div class="decision-grid">{''.join(f'<div class="decision-cell"><b>{v[0]} · {v[1]}</b><span>{v[4]}</span></div>' for v in variants)}</div></section></main>{modal}<script>{script}</script></body></html>'''
(root / 'bashlingo-directions.html').write_text(output,encoding='utf-8')
manifest=f'''# Данные дизайн-прототипа

Дата: 2026-11-13. Все четыре варианта используют одинаковые демонстрационные данные.

| Элемент | Поле / источник | Класс | Количество |
|---|---|---|---|
| Башкирская фраза и русский перевод в диалоге | dataset-sample.json, rows[].row.text_ba/text_ru, выбран id={record_id} | Real — текст источника, не экспертная проверка | 1 пара используется; {len(data.get('rows', [])) if sample.exists() else 0} строк загружено |
| 3 дня серии, 120 XP, 10/20 XP | user.streak, user.xp, daily.xp | Aspirational — иллюстративные значения | 0 настоящих профилей |
| Текущий урок и прогресс дорожки | user.lessonProgress | Aspirational | 0 записей прогресса |
| Знакомство, Семья, Школа | Согласованный бриф | Aspirational — структура курса согласована, контент ещё не подготовлен | 3 темы, 0 готовых уроков |
| Задание дня | dailyAssignment | Aspirational | 0 сгенерированных наборов; 5 упражнений предложено в брифе |
| От учителя: 6 карточек | class.assignment | Aspirational — демонстрационное число | 0 реальных назначений |
| Куница | Встроенный SVG | Real — созданная иллюстрация | 1 предварительный персонаж |
| Оценка перевода | translationFeedback | Aspirational — локальное переключение состояний | 0 сохранённых голосов |

Источник пары: https://huggingface.co/datasets/bashkorttele/trilingual-parallel-phrasebooks-bgpu, конфигурация ba-ru-alt, train. Варианты перевода и ошибки выравнивания могут присутствовать. В макете строка «Другой вариант» — явный UI-заполнитель, не готовый учебный дистрактор.
Датасет указывает CC BY 4.0; полная атрибуция из NOTICE должна быть добавлена при подготовке учебного корпуса. В макет импортирована только небольшая выборка для проверки дизайна.
Рабочие БД, API, Telegram и экспертная выгрузка ещё не реализованы. Редактирование и отправка замечания в диалоге не сохраняют данные.
'''
(root / 'bashlingo-directions.manifest.md').write_text(manifest,encoding='utf-8')
print('Created',root / 'bashlingo-directions.html')
print('Dataset record:', record_id)
